INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(127815, 'ruRU', '', 'Беги, если осмелишься, но далеко не уйдёшь!', 24330),
(127816, 'ruRU', '', 'Ты умрёшь от моей руки!', 24330),
(127817, 'ruRU', '', 'Я получу от этого удовольствие!', 24330),
(127818, 'ruRU', '', 'Это судьба, которую ты заслужил.', 24330),
(127819, 'ruRU', '', 'Иначе и быть не могло.', 24330),
(127820, 'ruRU', '', 'Слабые всегда гибнут.', 24330),
(127821, 'ruRU', '', 'Идите без меня. Я догоню.', 24330),
(127822, 'ruRU', '', 'Это поражение не сломит меня.', 24330),
(127823, 'ruRU', '', 'Мою волю не сломить!', 24330),
(127824, 'ruRU', '', 'Можешь доверить мне сделать всё, что нужно.', 24330),
(127825, 'ruRU', '', 'Твоя победа приносит надежду в сердца моего народа. Пылающий Легион никогда не захватит наши земли!', 24330),
(127897, 'ruRU', '', 'Пылающий Легион наступает на Вершину! Наши союзники вступили в бой с демонами по всем нашим землям. Чтобы переломить ход битвы, защитник, ты должен ударить в самое сердце их сил!', 24330),
(127898, 'ruRU', '', 'Отлично сражался! Наши силы одерживают пере...', 24330),
(127900, 'ruRU', '', 'Сама дикая природа Вершины восстаёт против демонов! Разбей инферналов и найди источник их вторжения.', 24330),
(127901, 'ruRU', '', 'Легион недооценивает упорство и решимость природы... и твои, я думаю!', 24330),
(127905, 'ruRU', '', '|TInterface\\Icons\\Ability_Butcher_Whirl.blp:20|t%s начинает применять |cFFFF0000|Hspell:232722|h[Рассекающий торнадо]|h|r!', 24330),
(127906, 'ruRU', '', '|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t%s призывает могучего Сарукела, чтобы раскрыть его |cFFFF0000|Hspell:234621|h[Прожорливую пасть]|h|r!', 24330),
(127908, 'ruRU', '', '|TInterface\\Icons\\ABILITY_WARLOCK_SOULLINK:20|t%s сковывает живую сущность с помощью |cFFFF0000|Hspell:236449|h[Узы душ]|h|r!', 24330),
(127909, 'ruRU', '', '|TInterface\\Icons\\SPELL_SHADOW_SHADESOFDARKNESS:20|t%s начинает высвобождать множество |cFFFF0000|Hspell:236075|h[Стенающих душ]|h|r!', 24330),
(127910, 'ruRU', '', 'Вместе мы раздробим кости бесчисленных демонов!', 24330),
(127912, 'ruRU', '', '|TInterface\\Icons\\Spell_Deathknight_Defile:20|tНе найдя душ в Мире духов, %s обрушивается с помощью |cFFFF0000|Hspell:236507|h[Покоя]|h|r!', 24330),
(127920, 'ruRU', '', 'Ах, неважно. Просто подожди, пока Могрейн не увидит, как мы летим вверх. Его аж пробьёт дрожь!', 24330),
(127931, 'ruRU', '', 'Иллидан! Будь проклят этот безрассудный охотник на демонов!', 24330),
(127932, 'ruRU', '', 'Иллидан оставил после себя беспорядок! Держись рядом... мы прорубим путь через этих демонов.', 24330),
(127933, 'ruRU', '', 'Я продолжу охоту на Иллидана. Ты разберись с этими тварями.', 24330),
(127936, 'ruRU', '', 'Ты и правда думал, что сможешь уйти от меня, Иллидан? Беги снова, и я закую тебя в цепи, как зверя, которым ты и являешься.', 24330),
(127939, 'ruRU', '', 'Столько смерти здесь... столько силы!', 24330),
(127940, 'ruRU', '', 'Разве не здесь случилось то, что вы, смертные, считаете своим величайшим унижением? Надеюсь, на этот раз тебе повезёт больше...', 24330),
(127941, 'ruRU', '', 'Не думаю, что эти земли видели такую бойню со времён Битвы за К\'тант. Так давно это было...', 24330),
(127949, 'ruRU', '', 'Это всегда было местом силы. Эгвин потянуло сюда, а до неё - эльфов, а до них - троллей. А до них...', 24330),
(127950, 'ruRU', '', 'То осквернённое сооружение, возвышающееся над этой землёй, блекнет по сравнению с величием того, что стояло здесь давным-давно.', 24330),
(127951, 'ruRU', '', 'Именно здесь, в давние века, Бог Глубин проиграл великую битву Богу Семи Голов. Но, как часто бывало, даже поражение в итоге обернулось в пользу Н\'Зота.', 24330),
(127953, 'ruRU', '', 'Эта мелкая стычка - не более чем отвлечение внимания. Настоящая битва приближается, пока круг близится к завершению.', 24330),
(127954, 'ruRU', '', 'Этот конфликт - лишь тень древней войны, что предшествовала вмешательству титанов. Бесчисленные армии сходились в непрекращающейся битве. Но я уверен, твоя маленькая война впечатляет... по-своему.', 24330),
(127955, 'ruRU', '', 'Мне потребовались века, чтобы вернуться на поверхность после Раскола. Наги бывают настолько ревностны к артефактам.', 24330),
(127956, 'ruRU', '', 'Эта земля видела столько потрясений. Катаклизм, Раскол, Опустошение... ты и представления не имеешь.', 24330),
(127957, 'ruRU', '', 'Ты был хорошим выбором. Ни один другой владелец не прокладывал себе путь убийствами через целый континент так, как ты. Я восхищаюсь твоей выносливостью.', 24330),
(127958, 'ruRU', '', 'Свет хотел бы, чтобы таким, как ты, оставались послушными и застывшими на месте. Я предлагаю дары свободы и силы. Надеюсь, ты запомнишь мою доброту.', 24330),
(127959, 'ruRU', '', 'Твои союзники считают меня дурным влиянием. Но всё, что я когда-либо делал - это ускорял твой путь по дороге, которую ты сам выбрал.', 24330),
(127960, 'ruRU', '', 'Я чувствую, как учащается пульс твоего мира. Скоро всё будет залито его жизненной кровью.', 24330);
